-- 09-indexes.sql
--
-- Extracted from artifacts/v1/gaos-arcadedb-model.html, which is the source of
-- truth for this schema, THEN RECONCILED against ArcadeDB 26.7.2. This file is
-- not verbatim: see RECONCILIATION.md, deviation 1, for what changed and why.
--
-- Do not edit this file to change the model -- change the document, then
-- re-extract and re-reconcile. A deviation that lives only here is a schema
-- nobody reviewing the model document would ever see, which is exactly the
-- failure RECONCILIATION.md exists to prevent.
--
-- Applied in filename order by deploy/schema/apply.sh. Every statement carries
-- IF NOT EXISTS, so applying twice is a no-op rather than an error.

-- Identity. Unique per tenant, not globally: ids are generated per tenant
-- and a restore of one tenant must not collide with another.
CREATE INDEX IF NOT EXISTS ON Product     (tenantId, id) UNIQUE;
CREATE INDEX IF NOT EXISTS ON Workflow    (tenantId, id) UNIQUE;
CREATE INDEX IF NOT EXISTS ON Task        (tenantId, id) UNIQUE;
CREATE INDEX IF NOT EXISTS ON TaskRun     (tenantId, id) UNIQUE;
CREATE INDEX IF NOT EXISTS ON Agent       (tenantId, id) UNIQUE;
CREATE INDEX IF NOT EXISTS ON Issue       (tenantId, id) UNIQUE;
CREATE INDEX IF NOT EXISTS ON Knowledge   (tenantId, id) UNIQUE;

-- THE scheduler index. Runs every tick, on every tenant, forever.
-- Order matters: equality columns first, then the ordering column.
CREATE INDEX IF NOT EXISTS ON Task (tenantId, status, priority) NOTUNIQUE;

-- Orphan detection on boot: RUNNING tasks whose lease has expired.
CREATE INDEX IF NOT EXISTS ON Task      (status, leaseUntil)    NOTUNIQUE;
CREATE INDEX IF NOT EXISTS ON Workspace (state, leaseUntil)     NOTUNIQUE;

-- Role matching for dispatch.
CREATE INDEX IF NOT EXISTS ON Agent (tenantId, role, availability) NOTUNIQUE;

-- Replay fold. Both orders are needed: per-entity for a task or workflow
-- replay, per-tenant for a floor replay and for the seq watermark.
CREATE INDEX IF NOT EXISTS ON Event (entityId, seq)  NOTUNIQUE;
CREATE INDEX IF NOT EXISTS ON Event (tenantId, seq)  UNIQUE;
CREATE INDEX IF NOT EXISTS ON Event (tenantId, ts)   NOTUNIQUE;
CREATE INDEX IF NOT EXISTS ON Snapshot (scope, scopeId, uptoSeq) NOTUNIQUE;

-- Back office listing and the readiness band gates.
CREATE INDEX IF NOT EXISTS ON Product (tenantId, readinessBand) NOTUNIQUE;

-- Impact analysis starts from a changed path.
CREATE INDEX IF NOT EXISTS ON File   (tenantId, path) NOTUNIQUE;
CREATE INDEX IF NOT EXISTS ON Commit (sha)            UNIQUE;

-- Retry intelligence: "have we seen this exact failure before?"
CREATE INDEX IF NOT EXISTS ON TaskRun (failureSignature) NOTUNIQUE;

-- Telemetry rollups.
CREATE INDEX IF NOT EXISTS ON Sample (series, ts) NOTUNIQUE;

-- Lesson recall by tag: BY ITEM indexes each element of the list.
CREATE INDEX IF NOT EXISTS ON Knowledge (tags BY ITEM) NOTUNIQUE;

-- Free-text search across the master record (Lucene-backed).
CREATE INDEX IF NOT EXISTS ON Requirement (text)    FULL_TEXT;
CREATE INDEX IF NOT EXISTS ON Knowledge   (summary) FULL_TEXT;

-- Optional: semantic lesson recall. Only if you populate embeddings.
-- Set dimensions to match your embedding model.
-- CREATE INDEX IF NOT EXISTS ON Knowledge (embedding) LSM_VECTOR
--   METADATA {dimensions: 1024, similarity: 'COSINE'};


-- ---------------------------------------------------------------------------
-- Edge uniqueness: one edge per ordered pair.
--
-- RECONCILED against ArcadeDB 26.7.2 -- see RECONCILIATION.md, deviation 1.
-- The model document declares these as `CREATE EDGE TYPE ... UNIQUE`, which
-- this engine rejects outright ("extraneous input 'UNIQUE'"). The constraint
-- itself is supported and is expressed as a unique index over the two
-- endpoints instead, which is what the `unique` column of the model's edge
-- catalog means: at most one edge per ordered pair.
--
-- All 32 concrete edge types carry it. CALLS is the one worth pausing on and
-- it is correct: repeated calls increment callCount on the single edge rather
-- than adding a second one.

CREATE INDEX IF NOT EXISTS ON OWNS            (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON HAS_REQUIREMENT (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON HAS_ISSUE       (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON HAS_CRITERION   (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON HAS_ARTIFACT    (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON TRACKS_METRIC   (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON USES_REPOSITORY (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON HAS_WORKFLOW    (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON HAS_TASK        (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON HAS_RUN         (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON CONTAINS        (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON CALLS           (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON DEPENDS_ON      (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON IMPLEMENTS      (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON SATISFIES       (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON EXECUTED_BY     (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON USES_WORKSPACE  (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON USES_PROMPT     (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON ASSEMBLED       (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON MODIFIES        (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON GENERATES       (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON USES_CONTEXT    (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON REVIEWED_BY     (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON GATED_BY        (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON LEARNS_FROM     (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON APPLIES_TO      (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON PRODUCES        (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON HAS_PARTICIPANT (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON DISCUSSES       (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON GOVERNS         (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON SEATED_IN       (`@out`, `@in`) UNIQUE;
CREATE INDEX IF NOT EXISTS ON RESERVED_BY     (`@out`, `@in`) UNIQUE;
